1	import type {
2	  ApiError,
3	  FeatureDetail,
4	  FeatureSummary,
5	  ImportWorkspaceRequest,
6	  PagedFeatures,
7	  PagedTasks,
8	  TaskDetail,
9	  TaskSummary,
10	  WorkspaceDetail,
11	} from "./types";
12	
13	function getApiBase(): string {
14	  const base = process.env.NEXT_PUBLIC_API_BASE_URL;
15	  if (!base) {
16	    throw new Error("NEXT_PUBLIC_API_BASE_URL is required for workflow-backend API calls");
17	  }
18	  return base;
19	}
20	
21	export async function request<T>(path: string, init?: RequestInit): Promise<T> {
22	  const res = await fetch(`${getApiBase()}${path}`, {
23	    ...init,
24	    headers: {
25	      Accept: "application/json",
26	      ...(init?.body ? { "Content-Type": "application/json" } : {}),
27	      ...(init?.headers || {}),
28	    },
29	  });
30	
31	  const text = await res.text();
32	  type ResponseBody = { success: boolean; data?: unknown; error?: ApiError };
33	  let body: ResponseBody | null = null;
34	  try {
35	    body = text ? (JSON.parse(text) as ResponseBody) : null;
36	  } catch {
37	    if (!res.ok) {
38	      throw { code: "PARSE_ERROR", message: `Non-JSON response (${res.status})`, retryable: res.status >= 500 } as ApiError;
39	    }
40	  }
41	
42	  if (!res.ok || body?.success === false) {
43	    throw (body?.error ?? {
44	      code: "UNKNOWN_ERROR",
45	      message: "Unknown backend API error",
46	      retryable: false,
47	    }) as ApiError;
48	  }
49	
50	  return body?.data as T;
51	}
52	
53	export async function importWorkspace(body: ImportWorkspaceRequest): Promise<WorkspaceDetail> {
54	  return request<WorkspaceDetail>("/api/workspaces/import", {
55	    method: "POST",
56	    body: JSON.stringify(body),
57	  });
58	}
59	
60	export async function getWorkspace(workspaceId: string): Promise<WorkspaceDetail> {
61	  return request<WorkspaceDetail>(`/api/workspaces/${workspaceId}`);
62	}
63	
64	export async function syncWorkspace(workspaceId: string): Promise<WorkspaceDetail> {
65	  return request<WorkspaceDetail>(`/api/workspaces/${workspaceId}/sync`, { method: "POST" });
66	}
67	
68	export async function searchFeatures(
69	  workspaceId: string,
70	  params?: URLSearchParams,
71	): Promise<FeatureSummary[]> {
72	  const qs = params?.toString() ? `?${params.toString()}` : "";
73	  const result = await request<FeatureSummary[] | PagedFeatures>(
74	    `/api/workspaces/${workspaceId}/features${qs}`,
75	  );
76	  return unwrapItems(result);
77	}
78	
79	export async function searchFeaturesPage(
80	  workspaceId: string,
81	  params?: URLSearchParams,
82	): Promise<PagedFeatures> {
83	  const qs = params?.toString() ? `?${params.toString()}` : "";
84	  const result = await request<FeatureSummary[] | PagedFeatures>(
85	    `/api/workspaces/${workspaceId}/features${qs}`,
86	  );
87	  return normalizePagedFeatures(result);
88	}
